/// <summary>
/// Represents the AVARUMWeightInHistory table class, providing methods for managing weight-in history records.
/// </summary>
public class AVARUMWeightInHistory extends common
{     
}

Method.Source:
/// <summary>
/// Finds a specific AVARUMWeightInHistory record by origin and step.
/// </summary>
/// <param name="_originId">The origin ID.</param>
/// <param name="_originRefTableId">The origin reference table ID.</param>
/// <param name="_originRefRecId">The origin reference record ID.</param>
/// <param name="_step">The step ID.</param>
/// <param name="_forUpdate">Indicates whether the record should be selected for update.</param>
/// <returns>
/// The found AVARUMWeightInHistory record, or null if not found.
/// </returns>
public static AVARUMWeightInHistory find(AVARUMWeightInOriginId _originId, RefTableId _originRefTableId, RefRecId _originRefRecId, AVARUMWeightInStepId _step, boolean _forUpdate = false)
{
    AVARUMWeightInHistory weightInHistory;

    weightInHistory.selectForUpdate(_forUpdate);

    select firstOnly weightInHistory
        where weightInHistory.OriginId == _originId &&
            weightInHistory.OriginRefTableId == _originRefTableId &&
            weightInHistory.OriginRefRecId == _originRefRecId &&
            weightInHistory.Step == _step;

    return weightInHistory;
}

/// <summary>
/// Finds a specific AVARUMWeightInHistory record by its GUID.
/// </summary>
/// <param name = "_id">The GUID of the record to find.</param>
/// <param name = "_forUpdate">Indicates whether the record should be selected for update.</param>
/// <returns>The found AVARUMWeightInHistory record, or null if not found.</returns>
public static AVARUMWeightInHistory findByGuid(AVARUMWeightInGuid _id, boolean _forUpdate = false)
{
    AVARUMWeightInHistory weightInHistory;

    weightInHistory.selectForUpdate(_forUpdate);

    select firstOnly weightInHistory
        where weightInHistory.Id == _id;

    return weightInHistory;
}

/// <summary>
/// Checks if a specific AVARUMWeightInHistory record exists.
/// </summary>
/// <param name="_originId">The origin ID.</param>
/// <param name="_originRefTableId">The origin reference table ID.</param>
/// <param name="_originRefRecId">The origin reference record ID.</param>
/// <param name="_step">The step ID.</param>
/// <returns>
/// true if the record exists; otherwise, false.
/// </returns>
public static boolean exist(AVARUMWeightInOriginId _originId, RefTableId _originRefTableId, RefRecId _originRefRecId, AVARUMWeightInStepId _step)
{
    return AVARUMWeightInHistory::find(_originId, _originRefTableId, _originRefRecId, _step).RecId != 0;
}

/// <summary>
/// Initializes a new AVARUMWeightInHistory record by copying from a reference and setting step and value.
/// </summary>
/// <param name="_reference">The reference AVARUMWeightInHistory record to copy from.</param>
/// <param name="_step">The step ID to set.</param>
/// <param name="_value">The value to set.</param>
/// <returns>
/// The initialized AVARUMWeightInHistory record.
/// </returns>
public static AVARUMWeightInHistory initByReference(AVARUMWeightInHistory _reference, AVARUMWeightInStepId _step, AVARUMWeightInValue _value)
{
    AVARUMWeightInHistory weightInHistory;                               

    weightInHistory.clear();
    weightInHistory.initValue();

    Global::buf2Buf(_reference, weightInHistory);
    weightInHistory.Id = newGuid();
    weightInHistory.RecId = 0;
    weightInHistory.Step = _step;
    weightInHistory.Value = _value;
    weightInHistory.StatusId = AVARUMWeightInStatus::New;

    // Enable overwriting system fields and preserve original
    weightInHistory.updateDateTimeFieldInfo(_reference.ModifiedBy);

    return weightInHistory;
}

/// <summary>
/// Checks if the weight-in process is done for a specific origin.
/// </summary>
/// <param name="_originId">The origin ID.</param>
/// <param name="_originRefTableId">The origin reference table ID.</param>
/// <param name="_originRefRecId">The origin reference record ID.</param>
/// <returns>
/// true if the process is done (step is Amount); otherwise, false.
/// </returns>
public static boolean isDone(AVARUMWeightInOriginId _originId, RefTableId _originRefTableId, RefRecId _originRefRecId)
{
    return AVARUMWeightInHistory::exist(_originId, _originRefTableId, _originRefRecId, AVARUMWeightInStep::Amount);
}

/// <summary>
/// Validates the specified field in the AVARUMWeightInHistory record.
/// </summary>
/// <param name = "_fieldIdToCheck">The field ID to validate.</param>
/// <returns>True if the field is valid; otherwise, false.</returns>
public boolean validateField(FieldId _fieldIdToCheck)
{
    boolean ret;

    ret = super(_fieldIdToCheck);

    switch (_fieldIdToCheck)
    {
        case fieldNum(AVARUMWeightInHistory, Identifier):
            ret = strLen(this.Identifier) > 0;

            if (!ret)
            {                 
                Global::warning("@AVARUM:WeightInIdentifierMandatory");
            }
            break;
    }

    return ret;
}

/// <summary>
/// Sets a new GUID for the AVARUMWeightInHistory record if it doesn't already have one.
/// </summary>
private void setGuid()
{
    guid id;     

    try   
    {     
        id = this.Id;

        if (this.Id == Global::emptyGuid())
        {
            id = newGuid();
        }
    }
    catch
    {
        id = newGuid();
    }

    this.Id = id;       
}

/// <summary>
/// Initializes the AVARUMWeightInHistory record with default values.
/// </summary>
public void initValue()
{
    super();

    this.setGuid();
    this.Value = 0; 
    this.StatusId = AVARUMWeightInStatus::New;
    this.message = '';
}

/// <summary>
/// Inserts a new AVARUMWeightInHistory record
/// </summary>
public void insert()
{
    this.setGuid();

    super();

    this.updateLoadFlag();
}

/// <summary>
/// Inserts a new AVARUMWeightInHistory record
/// </summary>
public void doInsert()
{
    this.setGuid();

    super();
}

/// <summary>
/// Displays the message associated with the AVARUMWeightInHistory record, resolving label IDs to strings if necessary.
/// </summary>    
[SysClientCacheDataMethodAttribute(true)] 
public display AVARUMWeightInMessage message()
{
    AVARUMWeightInMessage message;

    message = this.Message;

    if (SysLabel::isLabelId(message))
    {
        message = SysLabel::labelId2String(message, Global::currentUserLanguage());
    }

    return message;
}

[SysClientCacheDataMethodAttribute(true)]    
/// <summary>
/// Checks if the AVARUMWeightInHistory record has been processed (status is OK or Error).
/// </summary>
/// <returns>True if processed; otherwise, false.</returns>
public display AVARUMWeightInIsProcessedId isProcessed()
{                           
    AVARUMWeightInIsProcessedId isProcessed;

    isProcessed = this.StatusId == AVARUMWeightInStatus::OK || this.StatusId == AVARUMWeightInStatus::Error;

    return isProcessed;
}

/// <summary>
/// Displays the status image for the AVARUMWeightInHistory record based on its status ID.
/// </summary>
/// <returns>The image container representing the status.</returns>       
[SysClientCacheDataMethodAttribute(true)]
public display AVARUMStatusImage statusImage()
{
    ImageReference imgRef;
    AVARUMStatusImage statusImage;

    switch (this.StatusId)
    {               
        case AVARUMWeightInStatus::New:
            imgRef = ImageReference::constructForSymbol("DarkGraySquare");
            break;

        case AVARUMWeightInStatus::Pending:
            imgRef = ImageReference::constructForSymbol("YellowSquare");
            break;

        case AVARUMWeightInStatus::OK:
            imgRef = ImageReference::constructForSymbol("GreenSquare");
            break;

        case AVARUMWeightInStatus::Error:
            imgRef = ImageReference::constructForSymbol("RedSquare");
            break;

        default:
            imgRef = ImageReference::constructForSymbol("DarkGraySquare");
            break;
    }

    statusImage = imgRef.pack();

    return statusImage;
}

/// <summary>
/// Checks if the AVARUMWeightInHistory record has an error status.
/// </summary>
/// <returns>True if the status is Error; otherwise, false.</returns>
public boolean hasError()
{
    return this.StatusId == AVARUMWeightInStatus::Error;
}

/// <summary>
/// Updates the date and time fields (CreatedBy, CreatedDateTime, ModifiedBy, ModifiedDateTime) of the AVARUMWeightInHistory record.
/// </summary>
/// <param name = "_usereId">The user ID to set for the CreatedBy and ModifiedBy fields. Defaults to the current user ID if not provided.</param>
/// <param name = "_dateTime">The date and time to set for the CreatedDateTime and ModifiedDateTime fields. Defaults to the current UTC date and time if not provided.</param>
public void updateDateTimeFieldInfo(UserId _usereId = curUserId(), utcdatetime _dateTime = DateTimeUtil::utcNow())
{
    this.overwriteSystemfields(true);

    this.(fieldNum(AVARUMWeightInHistory, CreatedBy)) = _usereId;
    this.(fieldNum(AVARUMWeightInHistory, CreatedDateTime)) = _dateTime;
    this.(fieldNum(AVARUMWeightInHistory, ModifiedBy)) = _usereId;
    this.(fieldNum(AVARUMWeightInHistory, ModifiedDateTime)) = _dateTime;
}

/// <summary>
/// Update Weighing Flag on WHS Load after Weighing
/// </summary>
public void updateLoadFlag()
{
    WHSLoadLine locWHSLoadLine;
    if (this.OriginRefTableId==tableNum(PurchLine))
    {
        PurchLine locPurchLine;
        select firstonly LoadId from locWHSLoadLine
            join InventTransId from locPurchLine
            where locPurchLine.RecId==this.OriginRefRecId
              && locPurchLine.InventTransId==locWHSLoadLine.InventTransId
            && locWHSLoadLine.InventTransType==InventTransType::Purch;
    }
    else
    if (this.OriginRefTableId==tableNum(SalesLine))
    {
        SalesLine locSalesLine;
        select firstonly LoadId from locWHSLoadLine
            join InventTransId from locSalesLine
            where locSalesLine.RecId==this.OriginRefRecId
              && locSalesLine.InventTransId==locWHSLoadLine.InventTransId
            && locWHSLoadLine.InventTransType==InventTransType::Sales;
    }

    if (locWHSLoadLine.LoadId)
    {
        WHSLoadTable locWHSLoadTable;
        update_recordset locWHSLoadTable
            Setting AVARUMWeighing=true
            where locWHSLoadTable.LoadId==locWHSLoadLine.LoadId;
    }
}
